import os

import matplotlib

matplotlib.use("Agg")

import matplotlib.pyplot as plt
import matplotlib.patches
import pytest

from gen import FLATLINE_SENSOR, FLATLINE_START, N_SENSORS, generate
from plot_grid import PNG_FILE, SVG_FILE, build_figure, detect_flatline


@pytest.fixture(scope="module")
def data():
    _, d = generate()
    return d


@pytest.fixture(scope="module")
def fig():
    f = build_figure()
    yield f
    plt.close(f)


def test_flatline_detector(data):
    for s in range(N_SENSORS):
        runs = detect_flatline(data[s], run=60)
        if s == FLATLINE_SENSOR:
            assert runs == [(900, 1439)]
        else:
            assert runs == []


def test_exactly_six_axes(fig):
    assert len(fig.get_axes()) == 6


def test_shared_ylim_identical(fig):
    ylims = {ax.get_ylim() for ax in fig.get_axes()}
    assert len(ylims) == 1


def test_flatline_polygon_only_on_sensor4(fig):
    axes = fig.get_axes()
    # Axes order is row-major: sensor s -> axes[s // 3][s % 3]
    flat_ax = axes[FLATLINE_SENSOR // 3 * 3 + FLATLINE_SENSOR % 3]
    polys = [
        p for p in flat_ax.patches if isinstance(p, matplotlib.patches.Polygon)
    ]
    assert len(polys) == 1
    xs = polys[0].get_xy()[:, 0]
    assert xs.min() == pytest.approx(FLATLINE_START)
    assert xs.max() <= 1440
    for idx, ax in enumerate(axes):
        if idx == flat_ax:
            continue
        assert not any(
            isinstance(p, matplotlib.patches.Polygon) for p in ax.patches
        )


def test_png_valid_and_size():
    with open(PNG_FILE, "rb") as f:
        magic = f.read(8)
    assert magic == b"\x89PNG\r\n\x1a\n"
    assert os.path.getsize(PNG_FILE) > 20 * 1024


def test_svg_contains_sensor_4():
    text = open(SVG_FILE).read()
    assert "Sensor 4" in text

